      "codigo_refatorado": "using UnityEngine;\\nusing UnityEngine.Rendering;\\n\\npublic class AdaptiveGpuPerformanceController : MonoBehaviour\\n{\\n    [Header(\"Ajustes de Renderização\")]\\n    [SerializeField] private float targetFrameRate = 60.0f;\\n    [SerializeField] private float minRenderScale = 0.70f;\\n    [SerializeField] private float maxRenderScale = 1.0f;\\n    [SerializeField] private float scaleAdjustmentStep = 0.05f;\\n\\n    [Header(\"Sombras e Pós-Processamento\")]\\n    [SerializeField] private Light mainDirectionalLight;\\n    [SerializeField] private float highShadowDistance = 50f;\\n    [SerializeField] private float lowShadowDistance = 25f;\\n\\n    private float currentScale = 1.0f;\\n    private float sampleTimer = 0f;\\n    private const float EvaluationInterval = 0.5f;\\n\\n    private void Start()\\n    {SyncQualitySettings();}\\n\\n    private void Update()\\n    {\\n        sampleTimer += Time.unscaledDeltaTime;\\n        if (sampleTimer >= EvaluationInterval)\\n        {\\n            EvaluatePerformance();\\n            sampleTimer = 0f;\\n        }\\n    }\\n\\n    private void EvaluatePerformance()\\n    {\\n        float currentFps = 1.0f / Mathf.Max(Time.unscaledDeltaTime, 0.0001f);\\n        if (currentFps < (targetFrameRate - 5.0f))\\n        {\\n            currentScale = Mathf.Clamp(currentScale - scaleAdjustmentStep, minRenderScale, maxRenderScale);\\n            ApplyRenderScale(currentScale);\\n            if (QualitySettings.shadowDistance > lowShadowDistance)\\n            {\\n                QualitySettings.shadowDistance = lowShadowDistance;\\n                if (mainDirectionalLight != null)\\n                    mainDirectionalLight.shadowResolution = LightShadowResolution.Medium;\\n            }\\n        }\\n        else if (currentFps >= targetFrameRate && currentScale < maxRenderScale)\\n        {\\n            currentScale = Mathf.Clamp(currentScale + (scaleAdjustmentStep * 0.5f), minRenderScale, maxRenderScale);\\n            ApplyRenderScale(currentScale);\\n            if (QualitySettings.shadowDistance < highShadowDistance)\\n            {\\n                QualitySettings.shadowDistance = highShadowDistance;\\n                if (mainDirectionalLight != null)\\n                    mainDirectionalLight.shadowResolution = LightShadowResolution.High;\\n            }\\n        }\\n    }\\n\\n    private void ApplyRenderScale(float scale)\\n    {\\n        ScalableBufferManager.ResizeBuffers(scale, scale);\\n    }\\n\\n    private void SyncQualitySettings()\\n    {\\n        QualitySettings.shadowDistance = highShadowDistance;\\n        QualitySettings.shadowCascades = 2;\\n        QualitySettings.vSyncCount = 0;\\n        Application.targetFrameRate = 60;\\n        ApplyRenderScale(currentScale);\\n    }\\n}",
      "explicacao_didatica": "A placa de vídeo (GPU) está sobrecarregada, demorando o dobro do tempo aceitável para desenhar cada quadro na tela. Para resolver isso sem perder fluidez, criamos um controlador adaptativo que monitora os quadros por segundo. Se a taxa cair abaixo da meta de 60 FPS, o script reduz dinamicamente a escala interna de renderização e encurta a distância de projeção das sombras, aliviando o esforço de preenchimento de pixels da GPU instantaneamente."
    },
    {
      "tipo": "GC",
      "causa_raiz": "Ocorrência de pausas provocadas pelo Garbage Collector (gc_collect_ms: 5.58ms em um único quadro com 98KB alocados). Em taxas de atualização de 60 FPS (16.7ms de janela total), 5.58ms gastos apenas limpando memória residual roubam um terço do orçamento do frame, gerando 'engasgos' (stutters) perceptíveis.",
      "codigo_refatorado": "using UnityEngine;\\n\\npublic class NonAllocCollisionDetector : MonoBehaviour\\n{\\n    [SerializeField] private LayerMask targetLayer;\\n    [SerializeField] private float detectionRadius = 4f;\\n    private readonly Collider[] cachedHitColliders = new Collider[16];\\n\\n    private void Update()\\n    {\\n        PerformDetection();\\n    }\\n\\n    private void PerformDetection()\\n    {\\n        // Uso do OverlapSphereNonAlloc reutiliza o buffer sem instanciar arrays na Heap\\n        int hitsCount = Physics.OverlapSphereNonAlloc(transform.position, detectionRadius, cachedHitColliders, targetLayer);\\n\\n        for (int i = 0; i < hitsCount; i++)\\n        {\\n            Collider hit = cachedHitColliders[i];\\n            if (hit != null)\\n            {\\n                ProcessHit(hit);\\n            }\\n        }\\n    }\\n\\n    private void ProcessHit(Collider col)\\n    {\\n        // Lógica de processamento sem concatenação de strings ou alocações efêmeras\\n    }\\n}",
      "explicacao_didatica": "O Garbage Collector é o coletor de lixo da memória. Quando seu código cria objetos temporários a cada frame (como listas novas, strings ou comandos de física como Physics.OverlapSphere que devolvem um novo array), a memória enche e o Unity trava o jogo momentaneamente por 5ms para limpar tudo. A solução é pré-alocar estruturas fixas e usar métodos 'NonAlloc' para não gerar lixo a cada atualização."
    }
  ],
  "dicas_level_design": "Os Draw Calls ultrapassaram o teto (pico de 2797 contra o orçamento de 2579). Recomendações: (1) Otimização de Mesh e Materiais: Marque cenários estáticos como 'Batching Static' e configure Occlusion Culling na cena para descartar geometria oclusa; (2) Redução de Materiais Únicos: Utilize Texture Atlasing para fundir texturas de múltiplos props pequenos em uma única folha de textura compartilhando o mesmo material, permitindo Static/Dynamic Batching; (3) GPU Instancing: Ative a opção 'Enable GPU Instancing' nos materiais de elementos repetitivos (vegetação, detritos, postes, caixas); (4) LOD (Level of Detail): Configure grupos de LOD em prefabs complexos com transição agressiva para modelos simplificados e culling a distâncias moderadas; (5) Iluminação: Reduza luzes dinâmicas com sombra ativa; prefira luzes 'Baked' para superfícies estáticas e limite as fontes secundárias a luzes sem sombra projetada."
}

